<script setup lang="ts">
import { ref } from 'vue'
import { useI18n } from 'vue-i18n'
import SceneDesignCanvas from '@/components/common/SceneDesignCanvas.vue'
import PcPaperButton from '@/components/common/PcPaperButton.vue'
import { pcPaperIconUrl } from '@/presentation/assets/PcPaperIcons'
import { pcPaperControlStyles } from '@/presentation/assets/PcPaperControls'
import { resolveAssetUrl } from '@/presentation/assets/AssetBaseUrl'
import { DEFAULT_THANH_VAN_VARIANT, thanhVanLoadList } from '@/presentation/background/ThanhVanBackdropArt'
import { stableSceneArtUrl } from '@/presentation/huyenKim/StableSceneArt'
import '@/assets/pc-paper-scene.css'

const { t } = useI18n()
const choices = ['battle', 'victory', 'defeat', 'tribulation'] as const
type Example = typeof choices[number]
const requested = new URLSearchParams(window.location.search).get('example')
const example = ref<Example>(choices.includes(requested as Example) ? requested as Example : 'battle')
const notice = ref('')
const automatic = ref(false)
const layers = thanhVanLoadList(DEFAULT_THANH_VAN_VARIANT)
// The existing far-mountain layer has a baked checkerboard patch; omit it in this static review.
const background = [0, 2, 6, 3, 4, 5].map(index => resolveAssetUrl(layers[index]!.url))
const storm = ['tribulation-storm-far', 'tribulation-dais', 'tribulation-storm-near', 'tribulation-sky-vignette'].map(id => stableSceneArtUrl(id))
const art = {
  player: resolveAssetUrl('/assets/characters/player/mortal/player-mortal-ink-sword-concept-v2.png'),
  wolf: resolveAssetUrl('/assets/enemies/mortal/mortal-water-wolf-v1.png'),
  portrait: resolveAssetUrl('/assets/characters/animated/zuofeng/avatar/zuofeng-battle-status-avatar.png'),
  enemy: resolveAssetUrl('/assets/enemies/animated/graymane-wolf/avatar.png'),
  attack: resolveAssetUrl('/assets/ui/elements/el-metal.png'), skill: resolveAssetUrl('/assets/ui/elements/el-fire.png'), guard: resolveAssetUrl('/assets/ui/elements/el-earth.png'),
  stone: resolveAssetUrl('/assets/materials/linh_khoang.png'), ore: resolveAssetUrl('/assets/materials/linh_moc.png'),
  paper: resolveAssetUrl('/assets/ui/tien-hiep-2026-10/source/shared-paper-page-v1.png'),
  cloud: resolveAssetUrl('/assets/ui/tien-hiep-2026-10/source/shared-title-cloud-v1.png'),
}
const bars = [{ id: 'hp', value: '12 840 / 14 230', percent: 90 }, { id: 'mana', value: '2 130 / 3 000', percent: 71 }, { id: 'ward', value: '460 / 800', percent: 58 }]
function action() { notice.value = t('feedback') }
</script>

<template>
  <SceneDesignCanvas>
    <section class="co-stage" :data-design-example="example" :style="pcPaperControlStyles()">
      <div class="co-landscape" aria-hidden="true"><img v-for="(src, index) in example === 'tribulation' ? storm : background" :key="index" :src="src" alt=""></div>
      <template v-if="example === 'battle'">
        <header class="co-battle-heading co-ink"><img :src="pcPaperIconUrl('exploration')" alt=""><div><small>{{ t('zone') }}</small><h1>{{ t('stage') }}</h1></div><span>{{ t('round') }}</span></header>
        <aside class="co-player co-ink"><div class="co-identity"><img :src="art.portrait" alt=""><strong>{{ t('player') }}</strong></div><div v-for="bar in bars" :key="bar.id" class="co-resource"><label>{{ t(bar.id) }}<span>{{ bar.value }}</span></label><div class="co-track"><i :class="bar.id" :style="{ width: `${bar.percent}%` }" /></div></div></aside>
        <div class="co-fighters" aria-hidden="true"><img class="co-player-art" :src="art.player" alt=""><img class="co-wolf-art" :src="art.wolf" alt=""></div>
        <aside class="co-enemy co-ink"><strong>{{ t('enemy') }}</strong><label>{{ t('hp') }} <span>7 840 / 12 000</span></label><div class="co-track"><i class="hp" style="width:65%" /></div></aside>
        <section class="co-turns co-ink"><h2>{{ t('turns') }}</h2><ol><li v-for="n in 5" :key="n" :class="{ current: n === 1 }"><img :src="n === 1 ? art.portrait : art.enemy" alt=""><span>{{ t(n === 1 ? 'player' : 'wolf') }}</span><small>{{ n }}</small></li></ol></section>
