      </template>
      <template v-else>
        <header class="co-trial-heading co-ink"><h1>{{ t('realm') }}</h1><ol><li v-for="(id, index) in ['mind', 'body', 'lightning']" :key="id" :class="{ current: index === 2 }"><img :src="pcPaperIconUrl(index === 0 ? 'character' : index === 1 ? 'body' : 'realm')" alt="">{{ t(id) }}</li></ol></header>
        <img class="co-trial-character" :src="art.player" alt=""><aside class="co-trial-inspector pc-paper-inspector"><h2>{{ t('trial') }}</h2><h3>{{ t('progress') }}</h3><div class="co-track"><i class="ward" style="width:33%" /></div><p>3 / 9</p><h3>{{ t('resources') }}</h3><div v-for="bar in bars" :key="bar.id" class="co-resource"><label>{{ t(bar.id) }}<span>{{ bar.value }}</span></label><div class="co-track"><i :class="bar.id" :style="{ width: `${bar.percent}%` }" /></div></div><h3>{{ t('risk') }}</h3><p>{{ t('riskText') }}</p><PcPaperButton @click="action">{{ t('trialAction') }}</PcPaperButton></aside><p class="co-still-note">{{ t('trialHint') }}</p>
      </template>
      <p class="co-design-note">{{ t('sample') }}</p><p class="co-notice" role="status">{{ notice }}</p>
    </section>
  </SceneDesignCanvas>
</template>

